//! 📣️ Explicit owner registration separates generic history construction from registry I/O.
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_framework_space_history_explicit_owner_registration_after_create_reload_and_retained(){
 const CASE:&str="SEMIO_SQLITE_HISTORY_REGISTRATION_CASE";
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/📣️registration/🔣️.json")).unwrap();
 let Ok(case)=std::env::var(CASE)else{
  for sample in corpus["cases"].as_array().unwrap(){let id=sample["id"].as_str().unwrap();let output=std::process::Command::new(std::env::current_exe().unwrap()).arg("--exact").arg(format!("{}::sqlite_snapshot_framework_space_history_explicit_owner_registration_after_create_reload_and_retained",module_path!().split_once("::").expect("owning test module includes crate").1)).arg("--nocapture").env(CASE,id).output().unwrap();assert!(String::from_utf8_lossy(&output.stdout).contains("running 1 test"),"isolated owner-registration selector must execute its actual test: {}\n{}",String::from_utf8_lossy(&output.stdout),String::from_utf8_lossy(&output.stderr));assert!(output.status.success(),"isolated {id} explicit owner registration failed: {}\n{}",String::from_utf8_lossy(&output.stdout),String::from_utf8_lossy(&output.stderr));}
  return
 };
 let sample=corpus["cases"].as_array().unwrap().iter().find(|sample|sample["id"].as_str()==Some(case.as_str())).expect("exact isolated corpus case");
 let mode=sample["opening"].as_str().unwrap();let encoding=match sample["encoding"].as_str().unwrap(){"binary"=>SnapshotEncoding::Binary,"text"=>SnapshotEncoding::Text,_=>panic!("closed encoding corpus")};
 let source=fixture();let mut envelope=store::create_document_envelope::<SpaceHistorySnapshot,SpaceHistoryMutation>(S_SPACE_HISTORY_SCHEMA,"sqlite-history-registration",source.clone(),None);if mode=="retained"{envelope.dialect=Some(dialect());}
 let mut live=if mode=="retained"{
  let saved=store::print_document_pack(&envelope).await.unwrap();envelope.retire_unadopted();let history=store::os_spr::decode_history(&saved.spr,&store::os_spr::DecodeOptions::default()).await.unwrap();
  let mut open=store::RetainedPersistedDocumentHydration::<SpaceHistorySnapshot,SpaceHistoryMutation>::from_initial(source.clone(),history,store::os_io::ArtifactRef{artifact_id:"sqlite-history-registration".into(),dialect:dialect()},None,S_SPACE_HISTORY_SCHEMA.into(),store::test_support::plain_document_store_owners(),semio_framework_job::OperationId(1),semio_framework_job::Generation(1),u64::MAX,store::PersistedDocumentHydrationTarget::Store{generation:0});
  let cancellation=semio_framework_job::root_cancel_token();let mut preview_sequence=0;let mut ready=None;for _ in 0..100_000{let mut context=semio_framework_job::StepContext::new(semio_framework_job::OperationId(1),semio_framework_job::Generation(1),semio_framework_job::StepBudget::new(256,u64::MAX),cancellation.clone(),semio_framework_job::default_now_us,&mut preview_sequence);match open.step(&mut context){store::PersistedDocumentHydrationStep::Pending(_)=>{},store::PersistedDocumentHydrationStep::Ready(store::PersistedDocumentHydrationOutput::Store(member))=>{ready=Some(*member);break},_=>panic!("valid retained history must hand off its exact store")}}ready.expect("bounded retained opening must finish")
 }else{let envelope=if mode=="reload"{let saved=store::print_document_pack(&envelope).await.unwrap();envelope.retire_unadopted();store::parse_document_pack::<SpaceHistorySnapshot,SpaceHistoryMutation>(&saved.pack,&saved.spr).await.unwrap().into_envelope()}else{envelope};let mut live=store::ArtifactStore::new(envelope).await.unwrap();live.install_document_store_owners_exact(store::test_support::plain_document_store_owners());live};
 let expected_envelope_dialect=if sample["envelopeDialect"].is_null(){None}else{Some(dialect())};assert_eq!(live.envelope().dialect,expected_envelope_dialect);assert_eq!(*live.snapshot_ref(),source);
 assert_eq!(dialect().to_coordinate(),corpus["coordinate"].as_str().unwrap());assert_eq!(store::os_io::ArtifactDialect::from(store::space_history_sqlite::SQLITE_SNAPSHOT_DIALECT),dialect());
 let limits=SqliteDatabaseLimits::default();let mut independent=database();store::os_io::io_mechanism::attach_sqlite_snapshot_metadata(&mut independent,&dialect(),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let independent_bytes=export_sqlite_database(&independent,limits,&mut |_|true).unwrap();
 let export_refusal=store::os_io::io_mechanism::io_export_sqlite_snapshot(&dialect(),live.snapshot_ref(),encoding,limits,&mut |_|true).await.unwrap_err();assert_eq!(export_refusal.cause.kind,semio_framework_value::ValueRefusalKind::UnsupportedOwner);assert!(export_refusal.diagnostics.is_empty());
 let import_refusal=store::os_io::io_mechanism::io_import_sqlite_snapshot::<SpaceHistorySnapshot>(&dialect(),&independent_bytes,limits,&mut |_|true).await.unwrap_err();assert_eq!(import_refusal.cause.kind,semio_framework_value::ValueRefusalKind::UnsupportedOwner);assert!(import_refusal.diagnostics.is_empty());
 assert_eq!(live.envelope().dialect,expected_envelope_dialect);assert_eq!(*live.snapshot_ref(),source);
 store::space_history_sqlite::register_sqlite_snapshot().unwrap();
 let output=store::os_io::io_mechanism::io_export_sqlite_snapshot(&dialect(),live.snapshot_ref(),encoding,limits,&mut |_|true).await.unwrap();assert!(output.diagnostics.is_empty());let bytes=output.value;
 let relational=import_sqlite_database(&bytes,limits,&mut |_|true).unwrap();assert_eq!(relational,independent);assert_eq!(store::os_io::io_mechanism::sqlite_snapshot_metadata(&relational).unwrap(),(dialect(),encoding));
 let imported=store::os_io::io_mechanism::io_import_sqlite_snapshot::<SpaceHistorySnapshot>(&dialect(),&bytes,limits,&mut |_|true).await.unwrap();assert!(imported.diagnostics.is_empty());assert_eq!(imported.value,source);
 assert_eq!(store::os_io::io_mechanism::io_import_sqlite_snapshot::<SpaceHistorySnapshot>(&dialect(),&independent_bytes,limits,&mut |_|true).await.unwrap().value,source);
 let route=store::os_io::io_mechanism::io_route(&dialect(),&store::os_io::ArtifactDialect::from(store::io_schema::SQLITE_SNAPSHOT),1).await.unwrap().value;assert_eq!(route.hops.len(),sample["routeHops"].as_u64().unwrap()as usize);assert_eq!(route.hops[0].from,dialect());assert_eq!(route.hops[0].into,store::os_io::ArtifactDialect::from(store::io_schema::SQLITE_SNAPSHOT));
 assert_eq!(live.envelope().dialect,expected_envelope_dialect);assert_eq!(*live.snapshot_ref(),source);store::test_support::close_plain_test_store(&mut live);
 println!("[DEBUG] explicit SpaceHistory owner registration {case}: typed UnsupportedOwner before publication; complete state and exact SQLite metadata/route retained after publication");
}
